const ALLOWED_STEPS = [
    'pre_filter_verdict',
    'query_classification',
    'classification_confidence',
    'rag_documents_retrieved',
    'api_calls_made',
    'draft_response',
    'safety_verdict',
    'safety_reason',
    'final_response',
    'total_latency_ms',
    'llm_tokens_used'
];

const data = $input.item.json;

if (!data.request_id) {
    throw new Error('audit_logger called without request_id');
}

if (!data.step_name) {
    throw new Error('audit_logger called without step_name');
}

if (!ALLOWED_STEPS.includes(data.step_name)) {
    throw new Error(`Invalid step_name: "${data.step_name}". Allowed values: ${ALLOWED_STEPS.join(', ')}`);
}

return {
    json: {
        request_id: data.request_id,
        step_name: data.step_name,
        step_data: data.step_data ?? null,
        error: data.error || ''
    }
};
